input.content:
let stars = [];
let planets = [];
let asteroids = [];
let trails = [];
let timeSpeed = 1;
let dragStart = null;

function setup() {
  createCanvas(800, 600);

  // Generate background stars
  for (let i = 0; i < 150; i++) {
    stars.push({
      x: random(width),
      y: random(height),
      size: random(1, 3),
      twinkleSpeed: random(0.02, 0.08),
      twinkleOffset: random(TWO_PI)
    });
  }

  // Initialize planets: [name, distance, radius, speed, color, moonCount, ring]
  planets = [
    { name: "Mercury", dist: 55, radius: 4, speed: 0.04, color: color(180, 180, 180), angle: random(TWO_PI), moons: [] },
    { name: "Venus", dist: 85, radius: 7, speed: 0.025, color: color(225, 185, 120), angle: random(TWO_PI), moons: [] },
    {
      name: "Earth", dist: 125, radius: 8, speed: 0.018, color: color(100, 160, 255), angle: random(TWO_PI),
      moons: [{ dist: 15, radius: 2.5, speed: 0.08, angle: 0, color: color(220, 220, 220) }]
    },
    {
      name: "Mars", dist: 165, radius: 5.5, speed: 0.014, color: color(230, 100, 70), angle: random(TWO_PI),
      moons: [
        { dist: 11, radius: 1.5, speed: 0.09, angle: 0, color: color(190, 170, 160) },
        { dist: 16, radius: 1.2, speed: 0.06, angle: 2, color: color(170, 150, 140) }
      ]
    },
    {
      name: "Jupiter", dist: 230, radius: 16, speed: 0.008, color: color(210, 160, 110), angle: random(TWO_PI),
      moons: [
        { dist: 24, radius: 2.5, speed: 0.05, angle: 0, color: color(240, 230, 200) },
        { dist: 30, radius: 2.2, speed: 0.035, angle: 1.5, color: color(220, 200, 180) },
        { dist: 36, radius: 3, speed: 0.025, angle: 3.1, color: color(180, 180, 190) }
      ]
    },
    {
      name: "Saturn", dist: 300, radius: 13, speed: 0.006, color: color(235, 205, 150), angle: random(TWO_PI), hasRings: true,
      moons: [{ dist: 28, radius: 2.5, speed: 0.04, angle: 0, color: color(210, 210, 210) }]
    },
    { name: "Uranus", dist: 355, radius: 10, speed: 0.004, color: color(140, 220, 220), angle: random(TWO_PI), moons: [] },
    { name: "Neptune", dist: 390, radius: 9.5, speed: 0.003, color: color(80, 120, 240), angle: random(TWO_PI), moons: [] }
  ];
}

function draw() {
  background(10, 12, 22);

  let cx = width / 2;
  let cy = height / 2;

  // Draw twinkling stars
  noStroke();
  for (let s of stars) {
    let alphaVal = map(sin(frameCount * s.twinkleSpeed + s.twinkleOffset), -1, 1, 80, 255);
    fill(255, 255, 255, alphaVal);
    circle(s.x, s.y, s.size);
  }

  // Draw Sun glow and Sun
  push();
  translate(cx, cy);

  // Glow layers
  noStroke();
  for (let r = 50; r > 20; r -= 6) {
    let alphaGlow = map(r, 50, 20, 10, 60);
    fill(255, 180, 50, alphaGlow);
    circle(0, 0, r * 2);
  }

  // Sun core
  let sunPulse = sin(frameCount * 0.05) * 1.5;
  fill(255, 220, 90);
  circle(0, 0, 42 + sunPulse);
  fill(255, 245, 180);
  circle(0, 0, 32 + sunPulse * 0.5);

  // Draw orbit lines and planets
  let hoveredPlanet = null;
  let mRelX = mouseX - cx;
  let mRelY = mouseY - cy;

  for (let p of planets) {
    // Orbit track
    noFill();
    stroke(255, 255, 255, 25);
    strokeWeight(1);
    circle(0, 0, p.dist * 2);

    // Planet position
    p.angle += p.speed * timeSpeed;
    let px = cos(p.angle) * p.dist;
    let py = sin(p.angle) * p.dist;

    // Check hover
    let dToMouse = dist(mRelX, mRelY, px, py);
    let isHovered = dToMouse < p.radius + 6;
    if (isHovered) {
      hoveredPlanet = p;
    }

    // Draw planet shadow/body
    noStroke();
    fill(p.color);
    circle(px, py, p.radius * 2);

    // Highlight if hovered
    if (isHovered) {
      noFill();
      stroke(255, 255, 255, 180);
      strokeWeight(1.5);
      circle(px, py, p.radius * 2 + 6);
    }

    // Saturn rings
    if (p.hasRings) {
      push();
      translate(px, py);
      rotate(PI / 6);
      noFill();
      stroke(220, 190, 140, 160);
      strokeWeight(2.5);
      ellipse(0, 0, p.radius * 3.8, p.radius * 1.4);
      stroke(200, 170, 120, 100);
      strokeWeight(1.5);
      ellipse(0, 0, p.radius * 4.6, p.radius * 1.8);
      pop();
    }

    // Moons
    if (p.moons) {
      for (let m of p.moons) {
        m.angle += m.speed * timeSpeed;
        let mx = px + cos(m.angle) * m.dist;
        let my = py + sin(m.angle) * m.dist;

        // Moon orbit track
        noFill();
        stroke(255, 255, 255, 15);
        strokeWeight(1);
        circle(px, py, m.dist * 2);

        // Moon body
        noStroke();
        fill(m.color);
        circle(mx, my, m.radius * 2);
      }
    }
  }

  // Update and draw user launched asteroids / comets
  for (let i = asteroids.length - 1; i >= 0; i--) {
    let ast = asteroids[i];

    // Gravity towards sun
    let force = createVector(-ast.pos.x, -ast.pos.y);
    let d = force.mag();
    if (d > 10) {
      force.normalize();
      force.mult(120 / (d * 0.4 + 10));
      ast.vel.add(force.mult(0.05 * timeSpeed));
    }

    ast.pos.add(p5.Vector.mult(ast.vel, timeSpeed));
    ast.life--;

    // Asteroid trail
    ast.trail.push({ x: ast.pos.x, y: ast.pos.y });
    if (ast.trail.length > 25) {
      ast.trail.shift();
    }

    // Draw trail
    for (let t = 0; t < ast.trail.length - 1; t++) {
      let trailAlpha = map(t, 0, ast.trail.length - 1, 10, 180);
      stroke(ast.color.levels[0], ast.color.levels[1], ast.color.levels[2], trailAlpha);
      strokeWeight(map(t, 0, ast.trail.length - 1, 1, 3));
      line(ast.trail[t].x, ast.trail[t].y, ast.trail[t + 1].x, ast.trail[t + 1].y);
    }

    // Draw asteroid body
    noStroke();
    fill(ast.color);
    circle(ast.pos.x, ast.pos.y, ast.size);

    if (ast.life <= 0 || d < 20 || d > 900) {
      asteroids.splice(i, 1);
    }
  }

  pop();

  // Slingshot aim line when dragging
  if (dragStart) {
    stroke(255, 200, 50, 200);
    strokeWeight(2);
    line(dragStart.x, dragStart.y, mouseX, mouseY);
    fill(255, 200, 50);
    noStroke();
    circle(dragStart.x, dragStart.y, 6);
  }

  // UI overlay
  fill(240);
  noStroke();
  textSize(14);
  textAlign(LEFT, TOP);
  text("Tiny Solar System", 16, 16);
  textSize(11);
  fill(170, 180, 200);
  text("Drag & release mouse to launch comet\nPress SPACE to pause/resume | [C] to clear comets", 16, 36);

  if (hoveredPlanet) {
    fill(255, 230, 100);
    textSize(13);
    textAlign(RIGHT, TOP);
    text(hoveredPlanet.name + " (Orbit: " + round(hoveredPlanet.dist) + " AU)", width - 16, 16);
  }
}

function mousePressed() {
  dragStart = createVector(mouseX, mouseY);
}

function mouseReleased() {
  if (dragStart) {
    let launchVec = createVector(dragStart.x - mouseX, dragStart.y - mouseY).mult(0.05);
    let centerRelPos = createVector(dragStart.x - width / 2, dragStart.y - height / 2);

    asteroids.push({
      pos: centerRelPos,
      vel: launchVec,
      size: random(3, 6),
      color: color(random(180, 255), random(160, 220), random(200, 255)),
      life: 600,
      trail: []
    });
    dragStart = null;
  }
}

function keyPressed() {
  if (key === ' ' || keyCode === 32) {
    timeSpeed = timeSpeed === 0 ? 1 : 0;
  } else if (key === 'c' || key === 'C') {
    asteroids = [];
  }
}
